import 'package:flutter/material.dart';
import '../api.dart';

class PetProfileEditScreen extends StatefulWidget { const PetProfileEditScreen({super.key, required this.petId}); final String petId; @override State<PetProfileEditScreen> createState() => _PetProfileEditScreenState(); }
class _PetProfileEditScreenState extends State<PetProfileEditScreen> {
  final api = JopetsApi(); final name = TextEditingController(); final species = TextEditingController(); final breed = TextEditingController(); Map<String, dynamic>? pet; String? error; bool saving = false;
  @override void initState() { super.initState(); load(); }
  @override void dispose() { name.dispose(); species.dispose(); breed.dispose(); super.dispose(); }
  Future<void> load() async { try { final rows = await api.pets(); final matches = rows.where((row) => row['id']?.toString() == widget.petId); if (matches.isEmpty) throw const ApiException(404, 'Mascota no encontrada en el servidor'); final item = matches.first; name.text = item['name']?.toString() ?? ''; species.text = item['species']?.toString() ?? ''; breed.text = item['breed']?.toString() ?? ''; if (mounted) setState(() => pet = item); } catch (e) { if (mounted) setState(() => error = e.toString()); } }
  Future<void> save() async { setState(() => saving = true); try { await api.updatePet(widget.petId, {'name': name.text.trim(), 'species': species.text.trim(), 'breed': breed.text.trim()}); if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Perfil actualizado en el servidor'))); } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); } finally { if (mounted) setState(() => saving = false); } }
  @override Widget build(BuildContext context) { if (error != null) return Scaffold(appBar: AppBar(title: const Text('Perfil de mascota')), body: Center(child: Text(error!))); if (pet == null) return Scaffold(appBar: AppBar(title: const Text('Perfil de mascota')), body: const Center(child: CircularProgressIndicator())); return Scaffold(appBar: AppBar(title: const Text('Perfil de mascota')), body: ListView(padding: const EdgeInsets.all(20), children: [TextField(controller: name, decoration: const InputDecoration(labelText: 'Nombre')), TextField(controller: species, decoration: const InputDecoration(labelText: 'Especie')), TextField(controller: breed, decoration: const InputDecoration(labelText: 'Raza')), const SizedBox(height: 20), FilledButton(onPressed: saving ? null : save, child: Text(saving ? 'Guardando…' : 'Guardar cambios'))])); }
}
